// expect: exit 56
// screen: 0 odd 25, seven 56
int main(void)
{
    int i, odd = 0;
    for (i = 1; i <= 9; i++) {
        if (i % 2 == 0)
            continue;
        odd += i;
    }
    for (i = 51; i < 100; i++)
        if (i % 7 == 0)
            break;
    cls();
    printf("odd %d, seven %d\n", odd, i);
    return i;
}
